$pdo=Database::connect(['host'=>getenv('TEST_BACKUP_HOST'),'port'=>3306,'name'=>'update_backup','user'=>'backup','password'=>getenv('TEST_BACKUP_PASSWORD')]);$directory=sys_get_temp_dir().'/db-merge-'.bin2hex(random_bytes(8));mkdir($directory,0700);$count=0;$database=new UpdateDatabase($pdo);$merger=new UpdateDatabaseMerge($pdo);
