    $insert=$pdo->prepare('INSERT INTO merge_items VALUES(?,?,?,?)');foreach([[1,'old1',null,"old\0binary"],[2,'old2',null,null],[3,'old3',null,null]] as $row)$insert->execute($row);$pdo->exec("INSERT INTO merge_links VALUES(1,'old','keep')");
