    $check($rows[0][1]==='user1'&&$rows[0][2]===null&&$rows[0][3]==="user\0bytes\xff",'field merge preserves user edit and binary while undoing untouched migration field');$check($rows[1][1]==='old2'&&$rows[1][2]==='user note','editing one field preserves untouched old fields');
