    $pdo->exec("UPDATE merge_added SET value='migration seed' WHERE id=1");$pdo->exec('ALTER TABLE merge_items ADD COLUMN new_field TEXT NULL');$changedSchema=$snapshot('schema-current');$reject(fn()=>$merger->prepare($before,$baseline,$changedSchema,$directory.'/schema-merged.jsonl'),'UPDATE_DB_ROLLBACK_CONFLICT');$check($pdo->query("SHOW COLUMNS FROM merge_items LIKE 'new_field'")->fetchAll()!==[],'unexpected live schema change is never overwritten');
